BEGIN;
CREATE FUNCTION pg_temp.expect(label text,ok boolean) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL %',label;END IF;RAISE NOTICE 'PASS %',label;END$$;
CREATE FUNCTION pg_temp.reject(label text,statement text) RETURNS void LANGUAGE plpgsql AS $$DECLARE rejected boolean:=false;BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN rejected:=true;END;PERFORM pg_temp.expect(label,rejected);END$$;
CREATE TEMP TABLE f(o uuid,o2 uuid,a uuid,s uuid,u uuid,u2 uuid,t uuid,t2 uuid,b uuid,b2 uuid,r uuid,stamp timestamptz);
INSERT INTO f SELECT gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),clock_timestamp()-interval '10 minutes';
INSERT INTO public.vihem_organisations(id,name,slug,short_stay_enabled) SELECT o,'QA auto messages','qa-auto-'||o,true FROM f UNION ALL SELECT o2,'QA other','qa-other-'||o2,true FROM f;
INSERT INTO auth.users(id,email) SELECT a,a||'@example.invalid' FROM f UNION ALL SELECT s,s||'@example.invalid' FROM f;
INSERT INTO public.vihem_profiles(id,organisation_id,name,email,role,active) SELECT a,o,'QA Admin',a||'@example.invalid','admin',true FROM f UNION ALL SELECT s,o,'QA Staff',s||'@example.invalid','staff',true FROM f ON CONFLICT(id) DO UPDATE SET organisation_id=excluded.organisation_id,role=excluded.role,active=true;
INSERT INTO public.vihem_short_stay_units(id,organisation_id,name,beds24_enabled,beds24_room_id,beds24_property_id) SELECT u,o,'QA Room',true,'123','456' FROM f UNION ALL SELECT u2,o2,'Other Room',true,'789','987' FROM f;
INSERT INTO public.vihem_short_stay_message_templates(id,organisation_id,unit_id,name,translations) SELECT t,o,u,'Arrival','{"sv":"Hej [FIRST_NAME]","en":"Hi [FIRST_NAME]"}'::jsonb FROM f UNION ALL SELECT t2,o2,u2,'Other','{"en":"Other"}'::jsonb FROM f;
INSERT INTO public.vihem_short_stay_bookings(id,organisation_id,unit_id,beds24_booking_id,start_date,end_date,booking_type) SELECT b,o,u,'12345',(stamp AT TIME ZONE 'Europe/Stockholm')::date,(stamp AT TIME ZONE 'Europe/Stockholm')::date+1,'booking' FROM f UNION ALL SELECT b2,o2,u2,'99999',(stamp AT TIME ZONE 'Europe/Stockholm')::date,(stamp AT TIME ZONE 'Europe/Stockholm')::date+1,'booking' FROM f;
GRANT SELECT ON f TO authenticated,service_role;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true),set_config('request.jwt.claim.sub',s::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT pg_temp.reject('staff cannot save automatic rule',format('select public.vihem_save_guest_message_rule(%L,0,%L,%L,ARRAY[%L],%L,%L,0,%L,false)',r,u,t,'booking','en','arrival','10:00')) FROM f;
SELECT pg_temp.reject('authenticated cannot invoke delivery claim',format('select public.vihem_claim_guest_message(%L,1,%L,%L,now())',r,b,'Hi QA')) FROM f;
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true),set_config('request.jwt.claim.sub',a::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT public.vihem_save_guest_message_rule(r,0,u,t,ARRAY['booking','expedia'],'en','arrival',0,(stamp AT TIME ZONE 'Europe/Stockholm')::time,false) IS NOT NULL FROM f;
SELECT public.vihem_save_guest_message_rule(r,0,u,t,ARRAY['booking','expedia'],'en','arrival',0,(stamp AT TIME ZONE 'Europe/Stockholm')::time,false) IS NOT NULL FROM f;
SELECT pg_temp.expect('lost create response retries one rule',(SELECT count(*)=1 FROM public.vihem_guest_message_rules));
SELECT pg_temp.expect('admin reads own rule',(SELECT count(*)=1 FROM public.vihem_guest_message_rules));
SELECT pg_temp.reject('admin cannot use foreign template',format('select public.vihem_save_guest_message_rule(%L,0,%L,%L,ARRAY[%L],%L,%L,0,%L,false)',gen_random_uuid(),u2,t2,'booking','en','arrival','10:00')) FROM f;
SELECT pg_temp.reject('missing translation rejected',format('select public.vihem_save_guest_message_rule(%L,0,%L,%L,ARRAY[%L],%L,%L,0,%L,true)',gen_random_uuid(),u,t,'booking','zz','arrival','10:00')) FROM f;
SELECT pg_temp.reject('direct admin writes denied',format('update public.vihem_guest_message_rules set enabled=true where id=%L',r)) FROM f;
SELECT public.vihem_save_guest_message_rule(r,1,u,t,ARRAY['booking','expedia'],'en','arrival',0,(stamp AT TIME ZONE 'Europe/Stockholm')::time,true) IS NOT NULL FROM f;
SELECT pg_temp.reject('stale revision rejected',format('select public.vihem_save_guest_message_rule(%L,1,%L,%L,ARRAY[%L],%L,%L,0,%L,false)',r,u,t,'booking','en','arrival','10:00')) FROM f;
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT pg_temp.expect('activation never backfills passed send time',public.vihem_claim_guest_message(r,2,b,'Hi QA',(select updated_at FROM public.vihem_short_stay_message_templates WHERE id=f.t)) IS NULL) FROM f;
RESET ROLE;
UPDATE public.vihem_guest_message_rules SET activated_at=clock_timestamp()-interval '1 day' WHERE id=(select r FROM f);
SET LOCAL ROLE service_role;
SELECT pg_temp.expect('another organisation booking rejected',public.vihem_claim_guest_message(r,2,b2,'Hi QA',(select updated_at FROM public.vihem_short_stay_message_templates WHERE id=f.t)) IS NULL) FROM f;
SELECT pg_temp.expect('stale template rejected',public.vihem_claim_guest_message(r,2,b,'Hi QA',now()-interval '1 day') IS NULL) FROM f;
SELECT pg_temp.expect('stale rule rejected',public.vihem_claim_guest_message(r,1,b,'Hi QA',(select updated_at FROM public.vihem_short_stay_message_templates WHERE id=f.t)) IS NULL) FROM f;
SELECT pg_temp.expect('one durable claim allowed',public.vihem_claim_guest_message(r,2,b,'Hi QA',(select updated_at FROM public.vihem_short_stay_message_templates WHERE id=f.t)) IS NOT NULL) FROM f;
SELECT pg_temp.expect('same booking cannot be claimed twice',public.vihem_claim_guest_message(r,2,b,'Hi QA',(select updated_at FROM public.vihem_short_stay_message_templates WHERE id=f.t)) IS NULL) FROM f;
SELECT pg_temp.expect('one job and one receipt created',(select count(*)=1 FROM public.vihem_guest_message_jobs WHERE organisation_id=f.o) AND (select count(*)=1 FROM public.vihem_short_stay_message_sends WHERE organisation_id=f.o)) FROM f;
RESET ROLE;
-- v2 is atomic, revision checked, and cannot bypass legacy role/org checks.
SELECT set_config('request.jwt.claim.sub',s::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT pg_temp.reject('staff cannot save v2',format('select public.vihem_save_guest_message_rule_v2(%L,2,%L,%L,ARRAY[%L],%L,%L,0,%L,false,%L)',r,u,t,'booking','en','arrival','10:00','auto')) FROM f;
RESET ROLE;
SELECT set_config('request.jwt.claim.sub',a::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT pg_temp.reject('v2 rejects foreign room',format('select public.vihem_save_guest_message_rule_v2(%L,2,%L,%L,ARRAY[%L],%L,%L,0,%L,false,%L)',r,u2,t2,'booking','en','arrival','10:00','auto')) FROM f;
SELECT pg_temp.reject('v2 rejects invalid mode',format('select public.vihem_save_guest_message_rule_v2(%L,2,%L,%L,ARRAY[%L],%L,%L,0,%L,false,%L)',r,u,t,'booking','en','arrival','10:00','unknown')) FROM f;
SELECT pg_temp.expect('failed changes preserve revision and mode',(SELECT revision=2 AND language_mode='fixed' FROM public.vihem_guest_message_rules WHERE id=(SELECT r FROM f)));
SELECT public.vihem_save_guest_message_rule_v2(r,2,u,t,ARRAY['booking'],'en','arrival',0,'10:00',false,'auto') FROM f;
SELECT pg_temp.expect('v2 changes mode atomically',(SELECT revision=3 AND language_mode='auto' AND NOT enabled FROM public.vihem_guest_message_rules WHERE id=(SELECT r FROM f)));
SELECT public.vihem_save_guest_message_rule_v2(b2,0,u,t,ARRAY['booking'],'en','departure',0,'10:00',false,'auto') FROM f;
SELECT public.vihem_save_guest_message_rule_v2(b2,0,u,t,ARRAY['booking'],'en','departure',0,'10:00',false,'auto') FROM f;
SELECT pg_temp.expect('v2 lost create response returns same rule',(SELECT count(*)=1 FROM public.vihem_guest_message_rules WHERE id=(SELECT b2 FROM f) AND revision=1 AND language_mode='auto'));
SELECT pg_temp.reject('v2 retry cannot change language mode',format('select public.vihem_save_guest_message_rule_v2(%L,0,%L,%L,ARRAY[%L],%L,%L,0,%L,false,%L)',b2,u,t,'booking','en','departure','10:00','fixed')) FROM f;
SELECT pg_temp.reject('auto activation needs fallback translation',format('select public.vihem_save_guest_message_rule_v2(%L,1,%L,%L,ARRAY[%L],%L,%L,0,%L,true,%L)',b2,u,t,'booking','zz','departure','10:00','auto')) FROM f;
SELECT pg_temp.expect('anon cannot call v2',NOT has_function_privilege('anon','public.vihem_save_guest_message_rule_v2(uuid,integer,uuid,uuid,text[],text,text,integer,time,boolean,text)','EXECUTE'));
SELECT pg_temp.reject('stale v2 rejected',format('select public.vihem_save_guest_message_rule_v2(%L,2,%L,%L,ARRAY[%L],%L,%L,0,%L,false,%L)',r,u,t,'booking','en','arrival','10:00','fixed')) FROM f;
SELECT public.vihem_save_guest_message_rule(r,3,u,t,ARRAY['booking'],'en','arrival',0,'10:00',false) FROM f;
SELECT pg_temp.expect('legacy save explicitly selects fixed language',(SELECT revision=4 AND language_mode='fixed' FROM public.vihem_guest_message_rules WHERE id=(SELECT r FROM f)));
RESET ROLE;
-- Keep original pause regression's expected revision for the fixture below.
UPDATE public.vihem_guest_message_rules SET revision=2 WHERE id=(SELECT r FROM f);
UPDATE public.vihem_short_stay_units SET beds24_enabled=false WHERE id=(SELECT u FROM f);
UPDATE public.vihem_short_stay_message_templates SET translations='{"sv":"Hej"}' WHERE id=(SELECT t FROM f);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true),set_config('request.jwt.claim.sub',a::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT public.vihem_save_guest_message_rule(r,2,u,t,ARRAY['booking'],'en','arrival',0,'10:00',false) FROM f;
SELECT pg_temp.expect('pause succeeds after room or language removed',(SELECT NOT enabled FROM public.vihem_guest_message_rules WHERE id=(SELECT r FROM f)));
SELECT pg_temp.reject('broken room or translation cannot be reactivated',format('select public.vihem_save_guest_message_rule(%L,3,%L,%L,ARRAY[%L],%L,%L,0,%L,true)',r,u,t,'booking','en','arrival','10:00')) FROM f;
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true),set_config('request.jwt.claim.sub',s::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT pg_temp.expect('staff cannot read rules or jobs',(SELECT count(*)=0 FROM public.vihem_guest_message_rules) AND (SELECT count(*)=0 FROM public.vihem_guest_message_jobs));
RESET ROLE;
UPDATE public.vihem_profiles SET organisation_id=(SELECT o2 FROM f) WHERE id=(SELECT a FROM f);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true),set_config('request.jwt.claim.sub',a::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT pg_temp.expect('other organisation admin cannot read rules or receipts',(SELECT count(*)=0 FROM public.vihem_guest_message_rules) AND (SELECT count(*)=0 FROM public.vihem_guest_message_jobs));
RESET ROLE;
ROLLBACK;
